def marcar_pareceres_manuais(apps, schema_editor):
    """Vendas cujo ÚLTIMO status foi decidido à mão passam a ser parecer manual.

    Só conta o histórico depois que a Esteira passou a se marcar ("Esteira Vivo: …", 19/10/2026):
    antes disso a importação antiga gravava sem marca, em rajadas (até 230 por minuto), e ficaria
    indistinguível de trabalho manual. Idempotente.
    """
    Hist = apps.get_model('fibras', 'FibraStatusHistory')
    Fibra = apps.get_model('fibras', 'Fibra')
    from django.db.models import Min
    inicio = Hist.objects.filter(retorno__startswith='Esteira Vivo:').aggregate(m=Min('alterado_em'))['m']
    if inicio is None:
        return
    ultimos = {}
    for fid, retorno, em, hid, por in (Hist.objects.order_by('fibra_id', 'alterado_em', 'id')
                                        .values_list('fibra_id', 'retorno', 'alterado_em', 'id', 'alterado_por_id')):
        ultimos[fid] = (retorno or '', em, por)
    for fid, (retorno, em, por) in ultimos.items():
        if em >= inicio and not retorno.startswith('Esteira Vivo:') and not retorno.startswith('Voltou a seguir'):
            Fibra.objects.filter(pk=fid, status_manual=False).update(status_manual=True, status_manual_em=em,
                                                                      status_manual_por_id=por)


